<?php
use App\Models\Event; use App\Models\MediaFile; use App\Services\GoogleDriveService; use Illuminate\Database\Eloquent\Builder; use Livewire\Component; use Livewire\WithFileUploads;
new class extends Component { use WithFileUploads; public string $uploadEventId=''; public bool $eventContext = false; public $mediaFile; public function mount(?int $contextEventId = null): void { if ($contextEventId !== null) { $this->uploadEventId = (string) $contextEventId; $this->eventContext = true; } } public function with():array{abort_unless(auth()->user()?->can('media.upload'),403);return ['events'=>$this->accessibleEvents()->orderBy('event_date')->pluck('name','id')];} public function upload():void{$data=$this->validate(['uploadEventId'=>['required','integer'],'mediaFile'=>['required','file','mimes:jpg,jpeg,png,webp,pdf','max:20480']]);abort_unless($this->accessibleEvents()->whereKey($data['uploadEventId'])->exists(),403);try{$u=app(GoogleDriveService::class)->upload($this->mediaFile->getRealPath(),$this->mediaFile->getClientOriginalName());MediaFile::query()->create(['event_id'=>$data['uploadEventId'],'uploaded_by'=>auth()->id(),'drive_file_id'=>$u['id'],'folder_id'=>data_get($u,'parents.0'),'name'=>$u['name']??$this->mediaFile->getClientOriginalName(),'mime_type'=>$u['mimeType']??$this->mediaFile->getMimeType(),'url'=>$u['webViewLink']??null,'metadata'=>$u]);session()->flash('success','Media berhasil diunggah ke Google Drive.');$this->redirectRoute('admin.media');}catch (\Throwable $e){$this->addError('mediaFile',$e->getMessage());}} private function accessibleEvents():Builder{$u=auth()->user();return Event::query()->when(!$u->hasRole('Super Admin'),fn(Builder $q):Builder=>$q->where(fn(Builder $q):Builder=>$q->where('created_by',$u->getKey())->orWhereHas('admins',fn(Builder $q):Builder=>$q->whereKey($u->getKey()))));} };
?>
<div class="mx-auto max-w-3xl space-y-8"><div class="flex flex-wrap items-end justify-between gap-4"><div><h1 class="text-3xl font-semibold text-brand-950">Upload media</h1></div><a href="{{ route('admin.media') }}" class="rounded-xl border border-slate-300 px-5 py-3 text-sm font-semibold text-slate-700">Kembali</a></div><form wire:submit="upload" class="space-y-5 rounded-3xl border border-slate-200 bg-white p-6 sm:p-8"><div><label class="text-sm font-semibold text-slate-700">Event tujuan</label>@if ($eventContext)<div class="mt-2 flex h-[50px] items-center justify-between rounded-xl border border-slate-300 bg-slate-100 px-4 py-3 text-slate-700"><span>{{ $events->get($uploadEventId, 'Event aktif') }}</span><i data-lucide="lock" class="size-4 text-slate-500"></i></div>@else<select wire:model="uploadEventId" class="mt-2 w-full px-4 py-3"><option value="">Pilih event</option>@foreach($events as $id=>$eventName)<option value="{{ $id }}">{{ $eventName }}</option>@endforeach</select>@endif</div><div><label class="text-sm font-semibold text-slate-700">File</label><input wire:model="mediaFile" type="file" accept=".jpg,.jpeg,.png,.webp,.pdf" class="mt-2 w-full"></div><div class="flex justify-end gap-3"><a href="{{ route('admin.media') }}" class="rounded-xl border border-slate-300 px-5 py-3 font-semibold text-slate-700">Batal</a><button class="rounded-xl bg-brand-950 px-5 py-3 font-semibold text-white">Upload media</button></div></form></div>